-- DDL Oracle do projeto MetroSP (FIAP Global Solution 2026/2).
-- Modelo correspondente ao mapeamento Spring Data JPA.
-- NAO EXECUTAR EM SCHEMA QUE JA POSSUI ESTAS TABELAS.
-- A API usa Flyway V1 e V2 em schemas novos; nao execute manualmente junto ao Flyway.
-- Schema novo, Oracle (nao rodar em DB que ja possui T_ESTACAO etc.)
CREATE TABLE T_ESTACAO (ID_ESTACAO NUMBER(38) NOT NULL, NM_ESTACAO VARCHAR2(200) NOT NULL, ORDEM NUMBER(2) NOT NULL, LINHA VARCHAR2(30), ATIVA CHAR(1), SENTIDO VARCHAR2(3), CONSTRAINT PK_ESTACAO PRIMARY KEY(ID_ESTACAO), CONSTRAINT CK_ESTACAO_ATIVA CHECK(ATIVA IN ('S','N')));
CREATE TABLE T_FUNCIONARIO (ID_FUNCIONARIO NUMBER(38) NOT NULL, NM_FUNCIONARIO VARCHAR2(200) NOT NULL, CPF CHAR(11) NOT NULL, EMAIL VARCHAR2(200), SENHA VARCHAR2(200), CARGO VARCHAR2(60) NOT NULL, CONSTRAINT PK_FUNCIONARIO PRIMARY KEY(ID_FUNCIONARIO));
CREATE TABLE T_USUARIO (ID_USUARIO NUMBER(38) NOT NULL, NM_USUARIO VARCHAR2(200) NOT NULL, EMAIL VARCHAR2(200) NOT NULL, SENHA VARCHAR2(200) NOT NULL, CONSTRAINT PK_USUARIO PRIMARY KEY(ID_USUARIO));
CREATE TABLE T_OCORRENCIA (ID_OCORRENCIAN NUMBER(38) NOT NULL, TIPO_PROBLEMA VARCHAR2(100) NOT NULL, MENSAGEM CLOB NOT NULL, STATUS CHAR(1) NOT NULL, DT_INICIO TIMESTAMP NOT NULL, DT_FIM TIMESTAMP, FK_ID_FUNCIONARIO NUMBER(38) NOT NULL, FK_ID_ESTACAO NUMBER(38) NOT NULL, CONSTRAINT PK_OCORRENCIA PRIMARY KEY(ID_OCORRENCIAN), CONSTRAINT FK_OCORR_FUNC FOREIGN KEY(FK_ID_FUNCIONARIO) REFERENCES T_FUNCIONARIO(ID_FUNCIONARIO), CONSTRAINT FK_OCORR_EST FOREIGN KEY(FK_ID_ESTACAO) REFERENCES T_ESTACAO(ID_ESTACAO));
CREATE UNIQUE INDEX UK_USUARIO_EMAIL ON T_USUARIO(EMAIL);
CREATE UNIQUE INDEX UK_FUNCIONARIO_EMAIL ON T_FUNCIONARIO(EMAIL);
CREATE SEQUENCE SEQ_ESTACAO START WITH 100 INCREMENT BY 1 NOCACHE;
CREATE SEQUENCE SEQ_FUNCIONARIO START WITH 100 INCREMENT BY 1 NOCACHE;
CREATE SEQUENCE SEQ_USUARIO START WITH 100 INCREMENT BY 1 NOCACHE;
CREATE SEQUENCE SEQ_OCORRENCIA START WITH 100 INCREMENT BY 1 NOCACHE;
